INSERT INTO campo_documento (campo_id,documento_id,ruta_campo,ocurrencia,rotulo_original,texto_original,estado_revision) VALUES (4001001,4001,'texto_extraido_integro',1,'Transcripción íntegra devuelta por Drive','Macroproceso: Formación'||char(13)||char(10)||'Proceso: Gestión Administrativa de Apoyo a la Formación'||char(13)||char(10)||'Formato convocatoria estudiantes auxiliares'||char(13)||char(10)||'Código: U.FT.05.007.013 Versión: 2.0 Página 1 de 3'||char(13)||char(10)||'Número de la'||char(13)||char(10)||'Convocatoria'||char(13)||char(10)||'2026-C2347'||char(13)||char(10)||'Fecha de publicación de la'||char(13)||char(10)||'convocatoria'||char(13)||char(10)||'09 11 2026'||char(13)||char(10)||'Nombre Facultad,'||char(13)||char(10)||'dependencia o proyecto'||char(13)||char(10)||'que convoca'||char(13)||char(10)||'ADENDA 2026-C2347-1 DEL 12/11/2026'||char(13)||char(10)||'Por la cual se corrige el nombre del proyecto y de la convocatoria quedando así:'||char(13)||char(10)||'FACULTAD DE MEDICINA - PROYECTO DE SOPORTE INSTITUCIONAL “SITUACIÓN'||char(13)||char(10)||'ALIMENTARIA Y NUTRICIONAL DE LOS ESTUDIANTES DE PREGRADO DE LA UNIVERSIDAD'||char(13)||char(10)||'NACIONAL DE COLOMBIA, SEDE BOGOTÁ'||char(13)||char(10)||'Nombre de la'||char(13)||char(10)||'convocatoria'||char(13)||char(10)||'PROYECTO DE SOPORTE INSTITUCIONAL “SITUACIÓN ALIMENTARIA Y NUTRICIONAL DE'||char(13)||char(10)||'LOS ESTUDIANTES DE PREGRADO DE LA UNIVERSIDAD NACIONAL DE COLOMBIA, SEDE'||char(13)||char(10)||'BOGOTÁ'||char(13)||char(10)||'Tipo de estudiante Pregrado ⛝ Posgrado ☐'||char(13)||char(10)||'Tipo de actividades a'||char(13)||char(10)||'desarrollar en la'||char(13)||char(10)||'convocatoria'||char(13)||char(10)||'☐ ☐ ☐ ☐ ⛝'||char(13)||char(10)||'Docencia'||char(13)||char(10)||'(Apoyo'||char(13)||char(10)||'Académico)'||char(13)||char(10)||'Apoyo a proyectos'||char(13)||char(10)||'investigación o'||char(13)||char(10)||'extensión'||char(13)||char(10)||'Gestión'||char(13)||char(10)||'Administrativa'||char(13)||char(10)||'Bienestar'||char(13)||char(10)||'universitario'||char(13)||char(10)||'Otro'||char(13)||char(10)||'No. de estudiantes a'||char(13)||char(10)||'vincular'||char(13)||char(10)||'10'||char(13)||char(10)||'Requisitos generales'||char(13)||char(10)||'(Art. 2 Acuerdo CSU 024'||char(13)||char(10)||'de 2022)'||char(13)||char(10)||'a. Tener la calidad de estudiante de pregrado o postgrado de la Universidad Nacional de'||char(13)||char(10)||'Colombia.'||char(13)||char(10)||'b. Si las actividades a desarrollar están relacionadas con docencia, el estudiante deberá tener'||char(13)||char(10)||'un Promedio Aritmético Ponderado Acumulado P.A.P.A. igual o superior a 3.5. para'||char(13)||char(10)||'estudiantes de pregrado, e igual o superior a 4.0 para estudiantes de posgrado'||char(13)||char(10)||'c. Si las actividades a desarrollar están relacionadas con investigación, extensión, bienestar'||char(13)||char(10)||'universitario o de gestión administrativa el estudiante deberá tener un Promedio Aritmético'||char(13)||char(10)||'Ponderado Acumulado P.A.P.A. igual o superior a 3.0. para estudiantes de pregrado, e igual o'||char(13)||char(10)||'superior a 4.0 para estudiantes de posgrado'||char(13)||char(10)||'d. No ostentar la calidad de monitor académico o becario, salvo para aquellos estudiantes que'||char(13)||char(10)||'obtuvieron la beca de posgrado por la distinción de Grado de Honor de la Universidad'||char(13)||char(10)||'Nacional de Colombia.'||char(13)||char(10)||'e. No tener calidad de funcionario público (administrativo o docente de planta) de la'||char(13)||char(10)||'Universidad Nacional de Colombia.'||char(13)||char(10)||'f. Durante el periodo lectivo el Estudiante Auxiliar debe mantener la calidad de estudiante e'||char(13)||char(10)||'inscrita al menos la carga mínima exigida por el Estatuto Estudiantil.'||char(13)||char(10)||'g. No haber tenido sanciones disciplinarias.'||char(13)||char(10)||'PARÁGRAFO 1. La figura de Estudiante Auxiliar podrá ser compatible con las modalidades de'||char(13)||char(10)||'apoyo a estudiantes en las cuales no se reciba una retribución económica por la realización de'||char(13)||char(10)||'actividades y que el desempeño como Estudiante Auxiliar no interfiera con el normal'||char(13)||char(10)||'desarrollo de su actividad académica.'||char(13)||char(10)||'PARÁGRAFO 2. Para los estudiantes de posgrado que se encuentren matriculados en el primer'||char(13)||char(10)||'periodo académico de un programa de posgrado cumplir una de las siguientes condiciones, de'||char(13)||char(10)||'acuerdo con el tipo de admisión, así:'||char(13)||char(10)||'1. Admisión regular. Se privilegia a los que hayan obtenido los mayores puntajes de admisión.'||char(13)||char(10)||'2. Haber sido admitido por admisión automática, según el literal c del artículo 57 del Acuerdo'||char(13)||char(10)||'008 de 2008 del Consejo Superior Universitario - Estatuto Estudiantil en sus disposiciones'||char(13)||char(10)||'académicas.Macroproceso: Formación'||char(13)||char(10)||'Proceso: Gestión Administrativa de Apoyo a la Formación'||char(13)||char(10)||'Formato convocatoria estudiantes auxiliares'||char(13)||char(10)||'Código: U.FT.05.007.013 Versión: 2.0 Página 2 de 3'||char(13)||char(10)||'3. Admisión mediante tránsito entre programas de posgrado, tener un promedio académico'||char(13)||char(10)||'igual o superior a 4.0 en el programa de posgrado desde el cual se aprobó el tránsito.'||char(13)||char(10)||'Perfil requerido Estudiantes de pregrado de Nutrición y Dietética'||char(13)||char(10)||'Avance de la carrera de 40%'||char(13)||char(10)||'P.A.P.A. igual o superior a 3.0'||char(13)||char(10)||'Estar vinculado al semillero de investigación de Seguridad Nutricional del Observatorio en'||char(13)||char(10)||'Soberanía y Seguridad Alimentaria y Nutricional'||char(13)||char(10)||'Disponibilidad horaria de lunes a viernes'||char(13)||char(10)||'Actividades a desarrollar'||char(13)||char(10)||'Apoyar la organización logística de las jornadas de recolección de información en la'||char(13)||char(10)||'Corporación de Residencias Universitarias (CRU) y en la Sede Bogotá.'||char(13)||char(10)||'Apoyar las actividades de convocatoria y comunicación con los estudiantes participantes en'||char(13)||char(10)||'las diferentes fases del proyecto.'||char(13)||char(10)||'Apoyar la preparación de los espacios, materiales, equipos e instrumentos necesarios para las'||char(13)||char(10)||'jornadas de trabajo de campo.'||char(13)||char(10)||'Apoyar el proceso de recolección de datos bajo los instrumentos orientados tanto de'||char(13)||char(10)||'medición antropométrica como de caracterización socioeconómica'||char(13)||char(10)||'Asistir a las reuniones de coordinación y apoyar las demás actividades que se requieran e'||char(13)||char(10)||'indiquen por parte de la coordinación del proyecto para el desarrollo del trabajo de campo.'||char(13)||char(10)||'Modalidad de las'||char(13)||char(10)||'actividades'||char(13)||char(10)||'⛝ ☐ ☐'||char(13)||char(10)||'Presencial Virtual Mixta'||char(13)||char(10)||'Disponibilidad de tiempo'||char(13)||char(10)||'requerida'||char(13)||char(10)||'20 H/semana'||char(13)||char(10)||'Estímulo económico'||char(13)||char(10)||'mensual'||char(13)||char(10)||'$ 1.642.700'||char(13)||char(10)||'Este estímulo es incompatible con el estímulo económico que se otorga por ostentar la calidad de'||char(13)||char(10)||'monitor académico o becario, salvo para aquellos estudiantes que obtuvieron la beca de posgrado por'||char(13)||char(10)||'la distinción de Grado de Honor de la Universidad Nacional de Colombia.'||char(13)||char(10)||'Duración de la vinculación'||char(13)||char(10)||'30 Días'||char(13)||char(10)||'Los Estudiantes Auxiliares no tendrán la calidad de empleados, trabajadores o contratistas. Su relación'||char(13)||char(10)||'es fundamentalmente académica y no constituye vínculo laboral ni contractual con la Universidad.'||char(13)||char(10)||'Forma de Selección'||char(13)||char(10)||'Verificación del perfil, será carácter eliminatorio'||char(13)||char(10)||'Verificación de los documentos enviados, será carácter eliminatorio'||char(13)||char(10)||'Avance de la carrera, será un caracter eliminatorio'||char(13)||char(10)||'Términos para la'||char(13)||char(10)||'presentación de'||char(13)||char(10)||'documentos'||char(13)||char(10)||'jveranoc@unal.edu.co; ccastroru@unal.edu.co con Asunto: Número de la convocatoria'||char(13)||char(10)||'Estudiante Auxiliar Pregrado.'||char(13)||char(10)||'Fecha de cierre de la'||char(13)||char(10)||'convocatoria'||char(13)||char(10)||'13/Nov/2026 07:00 a.m.Macroproceso: Formación'||char(13)||char(10)||'Proceso: Gestión Administrativa de Apoyo a la Formación'||char(13)||char(10)||'Formato convocatoria estudiantes auxiliares'||char(13)||char(10)||'Los estudiantes que se postulen para la presente convocatoria aceptan que sus datos personales (nombre completo y/o documento de'||char(13)||char(10)||'identificación, BPM o puntaje de admisión y P.A.P.A) sean publicados al momento de dar a conocer los resultados del proceso de selección por'||char(13)||char(10)||'los canales de divulgación que la Universidad disponga para tal fin.'||char(13)||char(10)||'En el marco normativo de la Ley 1581 de 2012, la Universidad Nacional de Colombia se permite informar que la información personal'||char(13)||char(10)||'recolectada mediante la presente Convocatoria de Estudiantes Auxiliares se rige bajo los principios rectores del Régimen de Protección de'||char(13)||char(10)||'Datos de la Universidad Nacional, Resolución de Rectoría No. 207 de 2021, en especial el de Legalidad y Veracidad o calidad, la cual puede ser'||char(13)||char(10)||'consultada en http://www.legal.unal.edu.co/rlunal/home/doc.jsp?d_i=97992. Sus datos se encuentran bajo medidas que garantizan la'||char(13)||char(10)||'seguridad, confidencialidad e integridad. Puede ejercer sus derechos como titular a conocer, actualizar, rectificar y revocar las autorizaciones'||char(13)||char(10)||'dadas a las finalidades aplicables a través de los canales dispuestos y disponibles en https://unal.edu.co/ o en el e-mail'||char(13)||char(10)||'protecdatos_na@unal.edu.co.'||char(13)||char(10)||'Código: U.FT.05.007.013 Versión: 2.0 Página 3 de 3'||char(13)||char(10)||'Documentación requerida'||char(13)||char(10)||'- Formato Único de Hoja de Vida http://www.unal.edu.co/dnp/Archivos_base/formato_vida.pdf'||char(13)||char(10)||'- Historia Académica del SIA.'||char(13)||char(10)||'- Fotocopia de la Cédula.'||char(13)||char(10)||'- Fotocopia del Carné de Estudiante.'||char(13)||char(10)||'- Horario de Clases.'||char(13)||char(10)||'- Certificación de pertenecer al semillero de investigación'||char(13)||char(10)||'- Formato de autorización de verificación de inhabilidades por delitos sexuales'||char(13)||char(10)||'Documentos opcionales'||char(13)||char(10)||'(no pueden ser'||char(13)||char(10)||'modificatorios)'||char(13)||char(10)||'Responsable de la'||char(13)||char(10)||'convocatoria'||char(13)||char(10)||'Sara Del Castillo Matamoros - Docente, sedelcastillom@unal.edu.co, Ext: 15111'||char(13)||char(10)||'Criterios de evaluación 1. P.A.P.A. 20%'||char(13)||char(10)||'2. Avance de la carrera 10%'||char(13)||char(10)||'3. Pertenecer al semillero de investigación 40%'||char(13)||char(10)||'4. Disponibilidad horaria 30%'||char(13)||char(10)||'Fecha límite de'||char(13)||char(10)||'Publicación de Resultados'||char(13)||char(10)||'04/Dic/2026 07:00 a.m.','sin_cotejo_visual');
