INSERT INTO pagina_pdf (pagina_id,documento_id,numero_pagina,texto_extraido_literal,metodo_extraccion,estado_revision_visual,notas) VALUES (400102,4001,2,'Macroproceso: Formación'||char(13)||char(10)||'Proceso: Gestión Administrativa de Apoyo a la Formación'||char(13)||char(10)||'Formato convocatoria estudiantes auxiliares'||char(13)||char(10)||'Código: U.FT.05.007.013 Versión: 2.0 Página 2 de 3'||char(13)||char(10)||'3. Admisión mediante tránsito entre programas de posgrado, tener un promedio académico'||char(13)||char(10)||'igual o superior a 4.0 en el programa de posgrado desde el cual se aprobó el tránsito.'||char(13)||char(10)||'Perfil requerido Estudiantes de pregrado de Nutrición y Dietética'||char(13)||char(10)||'Avance de la carrera de 40%'||char(13)||char(10)||'P.A.P.A. igual o superior a 3.0'||char(13)||char(10)||'Estar vinculado al semillero de investigación de Seguridad Nutricional del Observatorio en'||char(13)||char(10)||'Soberanía y Seguridad Alimentaria y Nutricional'||char(13)||char(10)||'Disponibilidad horaria de lunes a viernes'||char(13)||char(10)||'Actividades a desarrollar'||char(13)||char(10)||'Apoyar la organización logística de las jornadas de recolección de información en la'||char(13)||char(10)||'Corporación de Residencias Universitarias (CRU) y en la Sede Bogotá.'||char(13)||char(10)||'Apoyar las actividades de convocatoria y comunicación con los estudiantes participantes en'||char(13)||char(10)||'las diferentes fases del proyecto.'||char(13)||char(10)||'Apoyar la preparación de los espacios, materiales, equipos e instrumentos necesarios para las'||char(13)||char(10)||'jornadas de trabajo de campo.'||char(13)||char(10)||'Apoyar el proceso de recolección de datos bajo los instrumentos orientados tanto de'||char(13)||char(10)||'medición antropométrica como de caracterización socioeconómica'||char(13)||char(10)||'Asistir a las reuniones de coordinación y apoyar las demás actividades que se requieran e'||char(13)||char(10)||'indiquen por parte de la coordinación del proyecto para el desarrollo del trabajo de campo.'||char(13)||char(10)||'Modalidad de las'||char(13)||char(10)||'actividades'||char(13)||char(10)||'⛝ ☐ ☐'||char(13)||char(10)||'Presencial Virtual Mixta'||char(13)||char(10)||'Disponibilidad de tiempo'||char(13)||char(10)||'requerida'||char(13)||char(10)||'20 H/semana'||char(13)||char(10)||'Estímulo económico'||char(13)||char(10)||'mensual'||char(13)||char(10)||'$ 1.642.700'||char(13)||char(10)||'Este estímulo es incompatible con el estímulo económico que se otorga por ostentar la calidad de'||char(13)||char(10)||'monitor académico o becario, salvo para aquellos estudiantes que obtuvieron la beca de posgrado por'||char(13)||char(10)||'la distinción de Grado de Honor de la Universidad Nacional de Colombia.'||char(13)||char(10)||'Duración de la vinculación'||char(13)||char(10)||'30 Días'||char(13)||char(10)||'Los Estudiantes Auxiliares no tendrán la calidad de empleados, trabajadores o contratistas. Su relación'||char(13)||char(10)||'es fundamentalmente académica y no constituye vínculo laboral ni contractual con la Universidad.'||char(13)||char(10)||'Forma de Selección'||char(13)||char(10)||'Verificación del perfil, será carácter eliminatorio'||char(13)||char(10)||'Verificación de los documentos enviados, será carácter eliminatorio'||char(13)||char(10)||'Avance de la carrera, será un caracter eliminatorio'||char(13)||char(10)||'Términos para la'||char(13)||char(10)||'presentación de'||char(13)||char(10)||'documentos'||char(13)||char(10)||'jveranoc@unal.edu.co; ccastroru@unal.edu.co con Asunto: Número de la convocatoria'||char(13)||char(10)||'Estudiante Auxiliar Pregrado.'||char(13)||char(10)||'Fecha de cierre de la'||char(13)||char(10)||'convocatoria'||char(13)||char(10)||'13/Nov/2026 07:00 a.m.','segmentacion_por_cabecera_heuristica','pendiente','Los límites de página son estimados; revisar original PDF.');
