INSERT INTO pagina_pdf (pagina_id,documento_id,numero_pagina,texto_extraido_literal,metodo_extraccion,estado_revision_visual,notas) VALUES (400103,4001,3,'Macroproceso: Formación'||char(13)||char(10)||'Proceso: Gestión Administrativa de Apoyo a la Formación'||char(13)||char(10)||'Formato convocatoria estudiantes auxiliares'||char(13)||char(10)||'Los estudiantes que se postulen para la presente convocatoria aceptan que sus datos personales (nombre completo y/o documento de'||char(13)||char(10)||'identificación, BPM o puntaje de admisión y P.A.P.A) sean publicados al momento de dar a conocer los resultados del proceso de selección por'||char(13)||char(10)||'los canales de divulgación que la Universidad disponga para tal fin.'||char(13)||char(10)||'En el marco normativo de la Ley 1581 de 2012, la Universidad Nacional de Colombia se permite informar que la información personal'||char(13)||char(10)||'recolectada mediante la presente Convocatoria de Estudiantes Auxiliares se rige bajo los principios rectores del Régimen de Protección de'||char(13)||char(10)||'Datos de la Universidad Nacional, Resolución de Rectoría No. 207 de 2021, en especial el de Legalidad y Veracidad o calidad, la cual puede ser'||char(13)||char(10)||'consultada en http://www.legal.unal.edu.co/rlunal/home/doc.jsp?d_i=97992. Sus datos se encuentran bajo medidas que garantizan la'||char(13)||char(10)||'seguridad, confidencialidad e integridad. Puede ejercer sus derechos como titular a conocer, actualizar, rectificar y revocar las autorizaciones'||char(13)||char(10)||'dadas a las finalidades aplicables a través de los canales dispuestos y disponibles en https://unal.edu.co/ o en el e-mail'||char(13)||char(10)||'protecdatos_na@unal.edu.co.'||char(13)||char(10)||'Código: U.FT.05.007.013 Versión: 2.0 Página 3 de 3'||char(13)||char(10)||'Documentación requerida'||char(13)||char(10)||'- Formato Único de Hoja de Vida http://www.unal.edu.co/dnp/Archivos_base/formato_vida.pdf'||char(13)||char(10)||'- Historia Académica del SIA.'||char(13)||char(10)||'- Fotocopia de la Cédula.'||char(13)||char(10)||'- Fotocopia del Carné de Estudiante.'||char(13)||char(10)||'- Horario de Clases.'||char(13)||char(10)||'- Certificación de pertenecer al semillero de investigación'||char(13)||char(10)||'- Formato de autorización de verificación de inhabilidades por delitos sexuales'||char(13)||char(10)||'Documentos opcionales'||char(13)||char(10)||'(no pueden ser'||char(13)||char(10)||'modificatorios)'||char(13)||char(10)||'Responsable de la'||char(13)||char(10)||'convocatoria'||char(13)||char(10)||'Sara Del Castillo Matamoros - Docente, sedelcastillom@unal.edu.co, Ext: 15111'||char(13)||char(10)||'Criterios de evaluación 1. P.A.P.A. 20%'||char(13)||char(10)||'2. Avance de la carrera 10%'||char(13)||char(10)||'3. Pertenecer al semillero de investigación 40%'||char(13)||char(10)||'4. Disponibilidad horaria 30%'||char(13)||char(10)||'Fecha límite de'||char(13)||char(10)||'Publicación de Resultados'||char(13)||char(10)||'04/Dic/2026 07:00 a.m.','segmentacion_por_cabecera_heuristica','pendiente','Los límites de página son estimados; revisar original PDF.');
