INSERT INTO campo_documento (campo_id,documento_id,ruta_campo,ocurrencia,rotulo_original,texto_original,estado_revision) VALUES (4002001,4002,'texto_extraido_integro',1,'Transcripción íntegra devuelta por Drive','Macroproceso: Formación'||char(13)||char(10)||'Proceso: Gestión Administrativa de Apoyo a la Formación'||char(13)||char(10)||'Formato convocatoria estudiantes auxiliares'||char(13)||char(10)||'Código: U.FT.05.007.013 Versión: 2.0 Página 1 de 3'||char(13)||char(10)||'Número de la'||char(13)||char(10)||'Convocatoria'||char(13)||char(10)||'2026-C2260'||char(13)||char(10)||'Fecha de publicación de la'||char(13)||char(10)||'convocatoria'||char(13)||char(10)||'23 10 2026'||char(13)||char(10)||'Nombre Facultad,'||char(13)||char(10)||'dependencia o proyecto'||char(13)||char(10)||'que convoca'||char(13)||char(10)||'Facultad de Ingeniería - Laboratorio de innovación, creatividad y nuevas tecnologías LAB101'||char(13)||char(10)||'Nombre de la'||char(13)||char(10)||'convocatoria'||char(13)||char(10)||'Estudiantes de apoyo para la gestión de proyectos'||char(13)||char(10)||'Tipo de estudiante Pregrado ⛝ Posgrado ☐'||char(13)||char(10)||'Tipo de actividades a'||char(13)||char(10)||'desarrollar en la'||char(13)||char(10)||'convocatoria'||char(13)||char(10)||'☐ ⛝ ☐ ☐ ☐'||char(13)||char(10)||'Docencia'||char(13)||char(10)||'(Apoyo'||char(13)||char(10)||'Académico)'||char(13)||char(10)||'Apoyo a proyectos'||char(13)||char(10)||'investigación o'||char(13)||char(10)||'extensión'||char(13)||char(10)||'Gestión'||char(13)||char(10)||'Administrativa'||char(13)||char(10)||'Bienestar'||char(13)||char(10)||'universitario'||char(13)||char(10)||'Otro'||char(13)||char(10)||'No. de estudiantes a'||char(13)||char(10)||'vincular'||char(13)||char(10)||'2'||char(13)||char(10)||'Requisitos generales'||char(13)||char(10)||'(Art. 2 Acuerdo CSU 024'||char(13)||char(10)||'de 2022)'||char(13)||char(10)||'a. Tener la calidad de estudiante de pregrado o postgrado de la Universidad Nacional de'||char(13)||char(10)||'Colombia.'||char(13)||char(10)||'b. Si las actividades a desarrollar están relacionadas con docencia, el estudiante deberá tener'||char(13)||char(10)||'un Promedio Aritmético Ponderado Acumulado P.A.P.A. igual o superior a 3.5. para'||char(13)||char(10)||'estudiantes de pregrado, e igual o superior a 4.0 para estudiantes de posgrado'||char(13)||char(10)||'c. Si las actividades a desarrollar están relacionadas con investigación, extensión, bienestar'||char(13)||char(10)||'universitario o de gestión administrativa el estudiante deberá tener un Promedio Aritmético'||char(13)||char(10)||'Ponderado Acumulado P.A.P.A. igual o superior a 3.0. para estudiantes de pregrado, e igual o'||char(13)||char(10)||'superior a 4.0 para estudiantes de posgrado'||char(13)||char(10)||'d. No ostentar la calidad de monitor académico o becario, salvo para aquellos estudiantes que'||char(13)||char(10)||'obtuvieron la beca de posgrado por la distinción de Grado de Honor de la Universidad'||char(13)||char(10)||'Nacional de Colombia.'||char(13)||char(10)||'e. No tener calidad de funcionario público (administrativo o docente de planta) de la'||char(13)||char(10)||'Universidad Nacional de Colombia.'||char(13)||char(10)||'f. Durante el periodo lectivo el Estudiante Auxiliar debe mantener la calidad de estudiante e'||char(13)||char(10)||'inscrita al menos la carga mínima exigida por el Estatuto Estudiantil.'||char(13)||char(10)||'g. No haber tenido sanciones disciplinarias.'||char(13)||char(10)||'PARÁGRAFO 1. La figura de Estudiante Auxiliar podrá ser compatible con las modalidades de'||char(13)||char(10)||'apoyo a estudiantes en las cuales no se reciba una retribución económica por la realización de'||char(13)||char(10)||'actividades y que el desempeño como Estudiante Auxiliar no interfiera con el normal'||char(13)||char(10)||'desarrollo de su actividad académica.'||char(13)||char(10)||'PARÁGRAFO 2. Para los estudiantes de posgrado que se encuentren matriculados en el primer'||char(13)||char(10)||'periodo académico de un programa de posgrado cumplir una de las siguientes condiciones, de'||char(13)||char(10)||'acuerdo con el tipo de admisión, así:'||char(13)||char(10)||'1. Admisión regular. Se privilegia a los que hayan obtenido los mayores puntajes de admisión.'||char(13)||char(10)||'2. Haber sido admitido por admisión automática, según el literal c del artículo 57 del Acuerdo'||char(13)||char(10)||'008 de 2008 del Consejo Superior Universitario - Estatuto Estudiantil en sus disposiciones'||char(13)||char(10)||'académicas.'||char(13)||char(10)||'3. Admisión mediante tránsito entre programas de posgrado, tener un promedio académico'||char(13)||char(10)||'igual o superior a 4.0 en el programa de posgrado desde el cual se aprobó el tránsito.'||char(13)||char(10)||'Perfil requerido Estudiante de pregrado de Ingeniería de Sistemas, Ingeniería Industrial o carreras afines, que'||char(13)||char(10)||'se encuentre cursando quinto semestre en adelante.Macroproceso: Formación'||char(13)||char(10)||'Proceso: Gestión Administrativa de Apoyo a la Formación'||char(13)||char(10)||'Formato convocatoria estudiantes auxiliares'||char(13)||char(10)||'Código: U.FT.05.007.013 Versión: 2.0 Página 2 de 3'||char(13)||char(10)||'Debe contar con conocimientos en análisis y gestión de datos, desarrollo de aplicaciones,'||char(13)||char(10)||'manejo de sistemas de gestión de contenidos (CMS), herramientas de visualización de datos'||char(13)||char(10)||'como Power BI y fundamentos de programación y lenguajes de desarrollo de software.'||char(13)||char(10)||'Manejo de Microsoft Azure y sus servicios asociados.'||char(13)||char(10)||'Conocimientos básicos de Databricks y procesamiento de datos.'||char(13)||char(10)||'Manejo de bases de datos y lenguaje SQL y Conocimientos en herramientas de'||char(13)||char(10)||'automatización y servicios en la nube'||char(13)||char(10)||'Actividades a desarrollar'||char(13)||char(10)||'1) Apoyar el desarrollo y actualización de tableros de visualización de datos en Power BI, de'||char(13)||char(10)||'acuerdo con los requerimientos del proyecto.'||char(13)||char(10)||'2) Apoyar la recopilación, organización, procesamiento, validación y actualización de'||char(13)||char(10)||'información proveniente de diferentes fuentes de datos.'||char(13)||char(10)||'3) Apoyar la actualización, organización y carga de contenidos e información en sistemas de'||char(13)||char(10)||'gestión de contenidos (CMS).'||char(13)||char(10)||'4) Apoyar la estructuración, consolidación y mantenimiento de bases de datos y conjuntos de'||char(13)||char(10)||'información requeridos para el desarrollo del proyecto.'||char(13)||char(10)||'5) Apoyar la documentación técnica y funcional de los procesos, herramientas, tableros y'||char(13)||char(10)||'soluciones tecnológicas desarrolladas.'||char(13)||char(10)||'6) Apoyar la realización de pruebas funcionales y verificaciones de calidad sobre los tableros,'||char(13)||char(10)||'las cargas de información y las soluciones implementadas.'||char(13)||char(10)||'Modalidad de las'||char(13)||char(10)||'actividades'||char(13)||char(10)||'☐ ☐ ⛝'||char(13)||char(10)||'Presencial Virtual Mixta'||char(13)||char(10)||'Disponibilidad de tiempo'||char(13)||char(10)||'requerida'||char(13)||char(10)||'20 H/semana'||char(13)||char(10)||'Estímulo económico'||char(13)||char(10)||'mensual'||char(13)||char(10)||'$ 1.500.000'||char(13)||char(10)||'Este estímulo es incompatible con el estímulo económico que se otorga por ostentar la calidad de'||char(13)||char(10)||'monitor académico o becario, salvo para aquellos estudiantes que obtuvieron la beca de posgrado por'||char(13)||char(10)||'la distinción de Grado de Honor de la Universidad Nacional de Colombia.'||char(13)||char(10)||'Duración de la vinculación'||char(13)||char(10)||'3 Meses'||char(13)||char(10)||'NOTA IMPORTANTE: La duración solicitada (3 meses) puede exceder el 31 de diciembre de'||char(13)||char(10)||'2026. Por tal motivo puede existir una primera vinculación hasta el 31 de diciembre de 2026'||char(13)||char(10)||'y una segunda vinculación por el período restante en la vigencia 2027. En el caso en que no se'||char(13)||char(10)||'realice la vinculación en el año 2026, esta se hará en su totalidad en la vigencia del 2027.'||char(13)||char(10)||'Los Estudiantes Auxiliares no tendrán la calidad de empleados, trabajadores o contratistas. Su relación'||char(13)||char(10)||'es fundamentalmente académica y no constituye vínculo laboral ni contractual con la Universidad.'||char(13)||char(10)||'Forma de Selección'||char(13)||char(10)||'- Verificación del perfil.'||char(13)||char(10)||'- Verificación de los documentos enviados.'||char(13)||char(10)||'Términos para la'||char(13)||char(10)||'presentación de'||char(13)||char(10)||'documentos'||char(13)||char(10)||'Enviar los documentos al correo lab101_bog@unal.edu.co'||char(13)||char(10)||'Fecha de cierre de la'||char(13)||char(10)||'convocatoria'||char(13)||char(10)||'29/Oct/2026 04:00 p.m.Macroproceso: Formación'||char(13)||char(10)||'Proceso: Gestión Administrativa de Apoyo a la Formación'||char(13)||char(10)||'Formato convocatoria estudiantes auxiliares'||char(13)||char(10)||'Los estudiantes que se postulen para la presente convocatoria aceptan que sus datos personales (nombre completo y/o documento de'||char(13)||char(10)||'identificación, BPM o puntaje de admisión y P.A.P.A) sean publicados al momento de dar a conocer los resultados del proceso de selección por'||char(13)||char(10)||'los canales de divulgación que la Universidad disponga para tal fin.'||char(13)||char(10)||'En el marco normativo de la Ley 1581 de 2012, la Universidad Nacional de Colombia se permite informar que la información personal'||char(13)||char(10)||'recolectada mediante la presente Convocatoria de Estudiantes Auxiliares se rige bajo los principios rectores del Régimen de Protección de'||char(13)||char(10)||'Datos de la Universidad Nacional, Resolución de Rectoría No. 207 de 2021, en especial el de Legalidad y Veracidad o calidad, la cual puede ser'||char(13)||char(10)||'consultada en http://www.legal.unal.edu.co/rlunal/home/doc.jsp?d_i=97992. Sus datos se encuentran bajo medidas que garantizan la'||char(13)||char(10)||'seguridad, confidencialidad e integridad. Puede ejercer sus derechos como titular a conocer, actualizar, rectificar y revocar las autorizaciones'||char(13)||char(10)||'dadas a las finalidades aplicables a través de los canales dispuestos y disponibles en https://unal.edu.co/ o en el e-mail'||char(13)||char(10)||'protecdatos_na@unal.edu.co.'||char(13)||char(10)||'Código: U.FT.05.007.013 Versión: 2.0 Página 3 de 3'||char(13)||char(10)||'Documentación requerida'||char(13)||char(10)||'1. Certificados de experiencia laboral Solo en formato pdf.'||char(13)||char(10)||'2. Certificados de conocimientos, cursos debidamente certificados Solo en formato Pdf,'||char(13)||char(10)||'3. Formato Único Hoja de vida,'||char(13)||char(10)||'4. Carnet UNAL.'||char(13)||char(10)||'5. Formato de Inhabilidades Versión Vigente 2.0'||char(13)||char(10)||'6. Copia del documento de identidad'||char(13)||char(10)||'7. P.A.P.A'||char(13)||char(10)||'8. Recibo de Matrícula PBM'||char(13)||char(10)||'9. Certificado que evidencie el porcentaje de Avance de carrera'||char(13)||char(10)||'10. Formato Autorización para Verificación de Inhabilidad por Delitos Sexuales Cometidos'||char(13)||char(10)||'Contra Menores. (Obligatorio)'||char(13)||char(10)||'Documentos opcionales'||char(13)||char(10)||'(no pueden ser'||char(13)||char(10)||'modificatorios)'||char(13)||char(10)||'Responsable de la'||char(13)||char(10)||'convocatoria'||char(13)||char(10)||'Pablo Enrique Rodriguez Espinosa, perodrigueze@unal.edu.co, Cel: 3123513991'||char(13)||char(10)||'Criterios de evaluación 1. P.A.P.A. Requisito habilitante igual o superior a 3.0'||char(13)||char(10)||'2. P.B.M. 10%'||char(13)||char(10)||'3. Certificados de conocimientos en PDF. de 0 a 40 de un total de 100 puntos 40%'||char(13)||char(10)||'4. Experiencia Laboral o académica (resoluciones) relacionada de 0 a 30 de un total de 100'||char(13)||char(10)||'puntos 30%'||char(13)||char(10)||'5. Conocimientos adicionales en innovación y tecnologías emergentes, evaluados de 0 a 20 de'||char(13)||char(10)||'un total de 100 puntos = 20%'||char(13)||char(10)||'Fecha límite de'||char(13)||char(10)||'Publicación de Resultados'||char(13)||char(10)||'20/Nov/2026 05:00 p.m.[Página 1 de ]'||char(13)||char(10)||'ANEXO 2.'||char(13)||char(10)||'FORMATO PUBLICACIÓN DE RESULTADOS CONVOCATORIA ESTUDIANTE(S) AUXILIAR(ES)'||char(13)||char(10)||'Nombre de la Convocatoria Número de Convocatoria '||char(13)||char(10)||'Nº de '||char(13)||char(10)||'estudiantes a '||char(13)||char(10)||'vincular'||char(13)||char(10)||'Facultad, dependencia '||char(13)||char(10)||'o proyecto'||char(13)||char(10)||'Fecha de publicación '||char(13)||char(10)||'de la convocatoria'||char(13)||char(10)||'Fecha de publicación '||char(13)||char(10)||'de resultados '||char(13)||char(10)||'Estudiantes de apoyo para '||char(13)||char(10)||'la gestión de proyectos 2026-C2260 2'||char(13)||char(10)||'Facultad de Ingeniería - '||char(13)||char(10)||'Laboratorio de '||char(13)||char(10)||'innovación, creatividad '||char(13)||char(10)||'y nuevas tecnologías '||char(13)||char(10)||'LAB101'||char(13)||char(10)||'23/10/2026 12/11/2026'||char(13)||char(10)||'Requisitos Generales: (Art. 2 Acuerdo CSU 024 de 2022)'||char(13)||char(10)||'a. Tener la calidad de estudiante de la Universidad Nacional de Colombia.'||char(13)||char(10)||'b. Si las actividades a desarrollar están relacionadas con docencia, el estudiante deberá tener un Promedio Aritmético Ponderado Acumulado P.A.P.A. igual o superior a 3.5. para '||char(13)||char(10)||'estudiantes de pregrado, e igual o superior a 4.0 para estudiantes de posgrado.'||char(13)||char(10)||'c. Si las actividades a desarrollar están relacionadas con investigación, extensión, bienestar universitario o de gestión administrativa el estudiante deberá tener un'||char(13)||char(10)||'Promedio Aritmético Ponderado Acumulado P.A.P.A. igual o superior a 3.0. para estudiantes de pregrado, e igual o superior a 4.0 para estudiantes de posgrado.'||char(13)||char(10)||'d. No ostentar la calidad de monitor académico o becario, salvo para aquellos estudiantes que obtuvieron la beca de posgrado por la distinción de Grado de Honor de'||char(13)||char(10)||'la Universidad Nacional de Colombia.'||char(13)||char(10)||'e. No tener calidad de funcionario público (administrativo o docente de planta) de la Universidad Nacional de Colombia.'||char(13)||char(10)||'f. Durante el periodo lectivo el Estudiante Auxiliar debe mantener la calidad de estudiante e inscrita al menos la carga mínima exigida por el Estatuto Estudiantil.'||char(13)||char(10)||'g. No haber tenido sanciones disciplinarias. Para los estudiantes de posgrado que se encuentren matriculados en el primer periodo académico de un programa de posgrado cumplir '||char(13)||char(10)||'una de las siguientes condiciones, de acuerdo con el tipo de admisión, así:'||char(13)||char(10)||'1. Admisión regular. Se privilegia a los que hayan obtenido los mayores puntajes de admisión.'||char(13)||char(10)||'2. Haber sido admitido por admisión automática, según el literal c del artículo 57 del Acuerdo 008 de 2008 del Consejo Superior Universitario - Estatuto Estudiantil en sus '||char(13)||char(10)||'disposiciones académicas.'||char(13)||char(10)||'3. Admisión mediante tránsito entre programas de posgrado, tener un promedio académico igual o superior a 4.0 en el programa de posgrado desde el cual se aprobó el'||char(13)||char(10)||'tránsito.'||char(13)||char(10)||'Nota: El estudiante que se postule a la convocatoria, manifiesta conocer la normatividad relacionada con la convocatoria y autoriza a la universidad para realizar las verificaciones '||char(13)||char(10)||'pertinentes'||char(13)||char(10)||'PERFIL REQUERIDO'||char(13)||char(10)||'Estudiante de pregrado de Ingeniería de Sistemas, Ingeniería Industrial o carreras afines, que se encuentre cursando quinto semestre en adelante.'||char(13)||char(10)||'Debe contar con conocimientos en análisis y gestión de datos, desarrollo de aplicaciones, manejo de sistemas de gestión de contenidos (CMS), herramientas de '||char(13)||char(10)||'visualización de datos como Power BI y fundamentos de programación y lenguajes de desarrollo de software.'||char(13)||char(10)||'Manejo de Microsoft Azure y sus servicios asociados.'||char(13)||char(10)||'Conocimientos básicos de Databricks y procesamiento de datos.'||char(13)||char(10)||'Manejo de bases de datos y lenguaje SQL y Conocimientos en herramientas de automatización y servicios en la nube'||char(13)||char(10)||'CRITERIOS DE SELECCIÓN Y EVALUACIÓN'||char(13)||char(10)||'Criterios Ponderación'||char(13)||char(10)||'(Asigne el peso porcentual de cada criterio)[Página 2 de ]'||char(13)||char(10)||'P.A.'||char(13)||char(10)||'P.A'||char(13)||char(10)||'P.A.P.A. Requisito habilitante igual o mayor a 3.0'||char(13)||char(10)||'1 P.B.M. 10% 10%'||char(13)||char(10)||'2 Certificados de conocimientos en PDF. de 0 a 40 de un total de 100 puntos 40% 40%'||char(13)||char(10)||'3'||char(13)||char(10)||'Experiencia Laboral o académica (resoluciones) relacionada de 0 a 30 de un total de 100'||char(13)||char(10)||'puntos 30% 30%'||char(13)||char(10)||'4'||char(13)||char(10)||'Conocimientos adicionales en innovación y tecnologías emergentes, evaluados de 0 a 20 de'||char(13)||char(10)||'un total de 100 puntos = 20% 20%'||char(13)||char(10)||'Sumatoria porcentajes 100'||char(13)||char(10)||'DATOS DE LOS PARTICIPANTES'||char(13)||char(10)||'No Identificación Nombres y Apellidos'||char(13)||char(10)||'Puntaje por Criterio'||char(13)||char(10)||'(De 0 a 5) (PBM de 0 a 100)'||char(13)||char(10)||'PAPA PBM'||char(13)||char(10)||'(si aplica) 1 2 3 4 5 Total Seleccionado'||char(13)||char(10)||'1 1031642709 Willian Andres Cardenas Sandoval 3,6 9 9,2 40 20 20 0 89,2 X'||char(13)||char(10)||'2 1025530329 Miguel Angel Suarez Montiel 4,8 53 4,8 40 0 20 0 64,8 X'||char(13)||char(10)||'3 1024475566 Jordan Eduardo Pardo Llanos 4,7 34 6,7 2,5 10 7.5 0 26.5'||char(13)||char(10)||'4 1117808596 Frank Kenner Olmos Prada 4,2 14 8,7 0 0 12,5 0 21,2'||char(13)||char(10)||'5 1007856485 Diego Alexander Ibanez Torres 3,9 - 0 2,5 0 17,5 0 20'||char(13)||char(10)||'6 1115720088 Andres Felipe Calderon Guerrero 3,7 5 9,6 7,5 0 2,5 0 19,6'||char(13)||char(10)||'7 1005873009 Valentina Bonilla Martinez 4 3 9,8 2,5 0 5 0 17,3'||char(13)||char(10)||'• Se deben relacionar todos los participantes que aplicaron a la convocatoria.'||char(13)||char(10)||'• Si el (la-los) estudiante(s) incumple(n) alguno de los Requisitos mínimos no se debe continuar con la evaluación de la hoja de vida.'||char(13)||char(10)||'• En caso de empate en el puntaje total, se dará prelación a los estudiantes cuyos puntajes básicos de matrícula (PBM) sean los más bajos. (En caso que aplique)'||char(13)||char(10)||'• Marque una X en la columna "Seleccionado" para identificar el (los) ganador(es) de la convocatoria. '||char(13)||char(10)||'Certifico que el (los) estudiante(s) seleccionado(s) fue(ron) consultado(s) y manifiesta(n) no recibir ningún otro beneficio económico de la Universidad '||char(13)||char(10)||'Nacional de Colombia y que no está(n) inhabilitado(s) para ser vinculado(s) como Estudiante(s) Auxiliar(es), a su vez asumo la responsabilidad de todo el '||char(13)||char(10)||'proceso de selección del estudiante.'||char(13)||char(10)||'En caso de que no se haya seleccionado a ningún estudiante como ganador de la convocatoria especifique el motivo:'||char(13)||char(10)||'Observaciones: Se presentaron a esta convocatoria 07 estudiantes, de los cuales se seleccionaron a 2, Willian Andres Cardenas '||char(13)||char(10)||'Sandoval y a Miguel Angel Suarez Montiel quienes obtuvieron un mayor puntaje.'||char(13)||char(10)||'NOMBRE DEL RESPONSABLE DE LA '||char(13)||char(10)||'EVALUACIÓN: PABLO ENRIQUE RODRIGUEZ ESPINOSA'||char(13)||char(10)||'CARGO: Director'||char(13)||char(10)||'EXTENSIÓN: '||char(13)||char(10)||'CORREO: perodrigueze@unal.edu.co'||char(13)||char(10)||'__________________________________'||char(13)||char(10)||'(Original Firmado)'||char(13)||char(10)||'Universidad'||char(13)||char(10)||'Nacional'||char(13)||char(10)||'de Colombia','sin_cotejo_visual');
