INSERT INTO pagina_pdf (pagina_id,documento_id,numero_pagina,texto_extraido_literal,metodo_extraccion,estado_revision_visual,notas) VALUES (400201,4002,1,'Macroproceso: Formación'||char(13)||char(10)||'Proceso: Gestión Administrativa de Apoyo a la Formación'||char(13)||char(10)||'Formato convocatoria estudiantes auxiliares'||char(13)||char(10)||'Código: U.FT.05.007.013 Versión: 2.0 Página 1 de 3'||char(13)||char(10)||'Número de la'||char(13)||char(10)||'Convocatoria'||char(13)||char(10)||'2026-C2260'||char(13)||char(10)||'Fecha de publicación de la'||char(13)||char(10)||'convocatoria'||char(13)||char(10)||'23 10 2026'||char(13)||char(10)||'Nombre Facultad,'||char(13)||char(10)||'dependencia o proyecto'||char(13)||char(10)||'que convoca'||char(13)||char(10)||'Facultad de Ingeniería - Laboratorio de innovación, creatividad y nuevas tecnologías LAB101'||char(13)||char(10)||'Nombre de la'||char(13)||char(10)||'convocatoria'||char(13)||char(10)||'Estudiantes de apoyo para la gestión de proyectos'||char(13)||char(10)||'Tipo de estudiante Pregrado ⛝ Posgrado ☐'||char(13)||char(10)||'Tipo de actividades a'||char(13)||char(10)||'desarrollar en la'||char(13)||char(10)||'convocatoria'||char(13)||char(10)||'☐ ⛝ ☐ ☐ ☐'||char(13)||char(10)||'Docencia'||char(13)||char(10)||'(Apoyo'||char(13)||char(10)||'Académico)'||char(13)||char(10)||'Apoyo a proyectos'||char(13)||char(10)||'investigación o'||char(13)||char(10)||'extensión'||char(13)||char(10)||'Gestión'||char(13)||char(10)||'Administrativa'||char(13)||char(10)||'Bienestar'||char(13)||char(10)||'universitario'||char(13)||char(10)||'Otro'||char(13)||char(10)||'No. de estudiantes a'||char(13)||char(10)||'vincular'||char(13)||char(10)||'2'||char(13)||char(10)||'Requisitos generales'||char(13)||char(10)||'(Art. 2 Acuerdo CSU 024'||char(13)||char(10)||'de 2022)'||char(13)||char(10)||'a. Tener la calidad de estudiante de pregrado o postgrado de la Universidad Nacional de'||char(13)||char(10)||'Colombia.'||char(13)||char(10)||'b. Si las actividades a desarrollar están relacionadas con docencia, el estudiante deberá tener'||char(13)||char(10)||'un Promedio Aritmético Ponderado Acumulado P.A.P.A. igual o superior a 3.5. para'||char(13)||char(10)||'estudiantes de pregrado, e igual o superior a 4.0 para estudiantes de posgrado'||char(13)||char(10)||'c. Si las actividades a desarrollar están relacionadas con investigación, extensión, bienestar'||char(13)||char(10)||'universitario o de gestión administrativa el estudiante deberá tener un Promedio Aritmético'||char(13)||char(10)||'Ponderado Acumulado P.A.P.A. igual o superior a 3.0. para estudiantes de pregrado, e igual o'||char(13)||char(10)||'superior a 4.0 para estudiantes de posgrado'||char(13)||char(10)||'d. No ostentar la calidad de monitor académico o becario, salvo para aquellos estudiantes que'||char(13)||char(10)||'obtuvieron la beca de posgrado por la distinción de Grado de Honor de la Universidad'||char(13)||char(10)||'Nacional de Colombia.'||char(13)||char(10)||'e. No tener calidad de funcionario público (administrativo o docente de planta) de la'||char(13)||char(10)||'Universidad Nacional de Colombia.'||char(13)||char(10)||'f. Durante el periodo lectivo el Estudiante Auxiliar debe mantener la calidad de estudiante e'||char(13)||char(10)||'inscrita al menos la carga mínima exigida por el Estatuto Estudiantil.'||char(13)||char(10)||'g. No haber tenido sanciones disciplinarias.'||char(13)||char(10)||'PARÁGRAFO 1. La figura de Estudiante Auxiliar podrá ser compatible con las modalidades de'||char(13)||char(10)||'apoyo a estudiantes en las cuales no se reciba una retribución económica por la realización de'||char(13)||char(10)||'actividades y que el desempeño como Estudiante Auxiliar no interfiera con el normal'||char(13)||char(10)||'desarrollo de su actividad académica.'||char(13)||char(10)||'PARÁGRAFO 2. Para los estudiantes de posgrado que se encuentren matriculados en el primer'||char(13)||char(10)||'periodo académico de un programa de posgrado cumplir una de las siguientes condiciones, de'||char(13)||char(10)||'acuerdo con el tipo de admisión, así:'||char(13)||char(10)||'1. Admisión regular. Se privilegia a los que hayan obtenido los mayores puntajes de admisión.'||char(13)||char(10)||'2. Haber sido admitido por admisión automática, según el literal c del artículo 57 del Acuerdo'||char(13)||char(10)||'008 de 2008 del Consejo Superior Universitario - Estatuto Estudiantil en sus disposiciones'||char(13)||char(10)||'académicas.'||char(13)||char(10)||'3. Admisión mediante tránsito entre programas de posgrado, tener un promedio académico'||char(13)||char(10)||'igual o superior a 4.0 en el programa de posgrado desde el cual se aprobó el tránsito.'||char(13)||char(10)||'Perfil requerido Estudiante de pregrado de Ingeniería de Sistemas, Ingeniería Industrial o carreras afines, que'||char(13)||char(10)||'se encuentre cursando quinto semestre en adelante.','segmentacion_por_cabecera_heuristica','pendiente','Los límites de página son estimados; revisar original PDF.');
