INSERT INTO campo_documento (campo_id,documento_id,ruta_campo,ocurrencia,rotulo_original,texto_original,estado_revision) VALUES (4003001,4003,'texto_extraido_integro',1,'Transcripción íntegra devuelta por Drive','Macroproceso: Formación'||char(13)||char(10)||'Proceso: Gestión Administrativa de Apoyo a la Formación'||char(13)||char(10)||'Formato selección estudiantes auxiliares'||char(13)||char(10)||'Código: U.FT.05.007.014 Versión: 2.0 Página 1 de 2'||char(13)||char(10)||'Nombre de la convocatoria'||char(13)||char(10)||'Auxiliar de apoyo para el proyecto Hermes 67246 - Modelo de priorización de corredores para'||char(13)||char(10)||'la peatonalización del Centro Histórico de Bogotá mediante SIG y análisis multicriterio'||char(13)||char(10)||'Número de la convocatoria'||char(13)||char(10)||'2026-C2245 N.º de estudiantes '||char(13)||char(10)||'a vincular'||char(13)||char(10)||'2'||char(13)||char(10)||'Facultad, dependencia o '||char(13)||char(10)||'proyecto'||char(13)||char(10)||'Facultad de Ingeniería'||char(13)||char(10)||'Fecha de publicación de la '||char(13)||char(10)||'convocatoria 19 11 2026'||char(13)||char(10)||'Fecha de publicación de '||char(13)||char(10)||'resultados 13 11 2026'||char(13)||char(10)||'Requisitos Generales'||char(13)||char(10)||'(Art. 2 Acuerdo CSU 024 de '||char(13)||char(10)||'2022)'||char(13)||char(10)||'a. Tener la calidad de estudiante de pregrado o postgrado de la Universidad Nacional de Colombia. '||char(13)||char(10)||'b. Si las actividades a desarrollar están relacionadas con docencia, el estudiante deberá tener un '||char(13)||char(10)||'Promedio Aritmético Ponderado Acumulado - P.A.P.A. igual o superior a 3.5. para estudiantes de '||char(13)||char(10)||'pregrado, e igual o superior a 4.0 para estudiantes de posgrado. '||char(13)||char(10)||'c. Si las actividades a desarrollar están relacionadas con investigación, extensión, bienestar '||char(13)||char(10)||'universitario o de gestión administrativa el estudiante deberá tener un Promedio Aritmético '||char(13)||char(10)||'Ponderado Acumulado - P.A.P.A. igual o superior a 3.0. para estudiantes de pregrado, e igual o '||char(13)||char(10)||'superior a 4.0 para estudiantes de posgrado'||char(13)||char(10)||'d. No ostentar la calidad de monitor académico o becario, salvo para aquellos estudiantes que '||char(13)||char(10)||'obtuvieron la beca de posgrado por la distinción de Grado de Honor de la Universidad Nacional de '||char(13)||char(10)||'Colombia.'||char(13)||char(10)||'e. No tener calidad de funcionario público (administrativo o docente de planta) de la Universidad '||char(13)||char(10)||'Nacional de Colombia.'||char(13)||char(10)||'f. Durante el periodo lectivo el Estudiante Auxiliar debe mantener la calidad de estudiante e inscrita '||char(13)||char(10)||'al menos la carga mínima exigida por el Estatuto Estudiantil. '||char(13)||char(10)||'g. No haber tenido sanciones disciplinarias.'||char(13)||char(10)||'PARÁGRAFO 1. La figura de Estudiante Auxiliar podrá ser compatible con las modalidades de apoyo '||char(13)||char(10)||'a estudiantes en las cuales no se reciba una retribución económica por la realización de actividades y '||char(13)||char(10)||'que el desempeño como Estudiante Auxiliar no interfiera con el normal desarrollo de su actividad '||char(13)||char(10)||'académica. '||char(13)||char(10)||'PARÁGRAFO 2. Para los estudiantes de posgrado que se encuentren matriculados en el primer '||char(13)||char(10)||'periodo académico de un programade posgrado cumplir una de las siguientes condiciones, de '||char(13)||char(10)||'acuerdo con el tipo de admisión, así: '||char(13)||char(10)||'1. Admisión regular. Se privilegia a los que hayan obtenido los mayores puntajes de admisión.'||char(13)||char(10)||'2. Haber sido admitido por admisión automática, según el literal c del artículo 57 del Acuerdo 008 '||char(13)||char(10)||'de 2008 del Consejo Superior Universitario - Estatuto Estudiantil en sus disposiciones académicas.'||char(13)||char(10)||'3. Admisión mediante tránsito entre programas de posgrado, tener un promedio académico igual o '||char(13)||char(10)||'superior a 4.0 en el programa de posgrado desde el cual se aprobó el tránsito.'||char(13)||char(10)||'Perfil requerido Estudiante de Ingeniería Civil con avance del 50% de carrera que haya participado en un semillero'||char(13)||char(10)||'del área de tránsito, transporte o infraestructura'||char(13)||char(10)||'CRITERIOS DE SELECCIÓN Y EVALUACIÓN'||char(13)||char(10)||'Criterios Ponderación '||char(13)||char(10)||'(Asigne el peso porcentual de cada criterio)'||char(13)||char(10)||'1 PAPA 20'||char(13)||char(10)||'2 PBM 20'||char(13)||char(10)||'3 Hoja de vida 30'||char(13)||char(10)||'4 Entrevista 30'||char(13)||char(10)||'Sumatoria de '||char(13)||char(10)||'porcentajes 100Macroproceso: Formación'||char(13)||char(10)||'Proceso: Gestión Administrativa de Apoyo a la Formación'||char(13)||char(10)||'Formato selección estudiantes auxiliares'||char(13)||char(10)||'Código: U.FT.05.007.014 Versión: 2.0 Página 2 de 2'||char(13)||char(10)||'DATOS DE LOS PARTICIPANTES'||char(13)||char(10)||'No. Identificación'||char(13)||char(10)||'Puntaje por Criterio'||char(13)||char(10)||'(De 0 a 5) (PBM de 0 a 100)'||char(13)||char(10)||'*P.A.P.A. '||char(13)||char(10)||'O puntaje de '||char(13)||char(10)||'admisión '||char(13)||char(10)||'(PA) (SI/NO)'||char(13)||char(10)||'P.B.M.'||char(13)||char(10)||'(si '||char(13)||char(10)||'aplica)'||char(13)||char(10)||'1 2 3 4 5 6 7 Total Seleccionado'||char(13)||char(10)||'1 1121528985 3,9 36 16 13 23 30 82 X'||char(13)||char(10)||'2 1016912141 3,7 28 15 14 24 28 81 X'||char(13)||char(10)||'3 1001187737 3,7 50 15 10 25 26 76'||char(13)||char(10)||'• Se deben relacionar todos los participantes que aplicaron a la convocatoria.'||char(13)||char(10)||'• Si el (la-los) estudiante(s) incumple(n) alguno de los Requisitos mínimos no se debe continuar con la evaluación de la hoja de vida.'||char(13)||char(10)||'• En caso de empate en el puntaje total, se dará prelación a los estudiantes cuyos puntajes básicos de matrícula (PBM) sean los más '||char(13)||char(10)||'bajos. (En caso que aplique)'||char(13)||char(10)||'• Marque una X en la columna "Seleccionado" para identificar el (los) ganador(es) de la convocatoria.'||char(13)||char(10)||'• Marque con la palabra “Elegible” a el (la-los) estudiante(s) que quedará(n) en la lista de elegible(s).'||char(13)||char(10)||'Certifico que el (los) estudiante(s) seleccionado(s) fue(ron) consultado(s) y manifiesta(n) no recibir ningún otro beneficio '||char(13)||char(10)||'económico de la Universidad Nacional de Colombia y que no está(n) inhabilitado(s) para ser vinculado(s) como Estudiante(s) '||char(13)||char(10)||'Auxiliar(es), a su vez asumo la responsabilidad de todo el proceso de selección del estudiante.'||char(13)||char(10)||'En caso de que no se haya seleccionado a ningún estudiante como ganador de la convocatoria especifique el motivo:'||char(13)||char(10)||'Observaciones:'||char(13)||char(10)||'NOMBRE DEL '||char(13)||char(10)||'RESPONSABLE DE LA '||char(13)||char(10)||'EVALUACIÓN'||char(13)||char(10)||'William Castro García'||char(13)||char(10)||'CARGO Profesor Asociado'||char(13)||char(10)||'EXTENSIÓN 313-4940351'||char(13)||char(10)||'CORREO wcastrog@unal.edu.co'||char(13)||char(10)||'_________________________________'||char(13)||char(10)||'(Original Firmado'||char(13)||char(10)||'Los estudiantes que se postulen para la presente convocatoria aceptan que sus datos personales (nombre completo y/o documento de '||char(13)||char(10)||'identificación, BPM o puntaje de admisión y P.A.P.A) sean publicados al momento de dar a conocer los resultados del proceso de selección por '||char(13)||char(10)||'los canales de divulgación que la Universidad disponga para tal fin. En el marco normativo de la Ley 1581 de 2012, la Universidad Nacional de '||char(13)||char(10)||'Colombia se permite informar que la información personal recolectada mediante la presente Convocatoria de Estudiantes Auxiliares se rige '||char(13)||char(10)||'bajo los principios rectores del Régimen de Protección de Datos de la Universidad Nacional, Resolución de Rectoría No. 207 de 2021, en '||char(13)||char(10)||'especial el de Legalidad y Veracidad o calidad, la cual puede ser consultada en http://www.legal.unal.edu.co/rlunal/home/doc.jsp?d_i=97992. '||char(13)||char(10)||'Sus datos se encuentran bajo medidas que garantizan la seguridad, confidencialidad e integridad. Puede ejercer sus derechos como titular a '||char(13)||char(10)||'conocer, actualizar, rectificar y revocar las autorizaciones dadas a las finalidades aplicables a través de los canales dispuestos y disponibles en '||char(13)||char(10)||'https://unal.edu.co/ o en el e-mail protecdatos_na@unal.edu.co.','sin_cotejo_visual');
