INSERT INTO pagina_pdf (pagina_id,documento_id,numero_pagina,texto_extraido_literal,metodo_extraccion,estado_revision_visual,notas) VALUES (400301,4003,1,'Macroproceso: Formación'||char(13)||char(10)||'Proceso: Gestión Administrativa de Apoyo a la Formación'||char(13)||char(10)||'Formato selección estudiantes auxiliares'||char(13)||char(10)||'Código: U.FT.05.007.014 Versión: 2.0 Página 1 de 2'||char(13)||char(10)||'Nombre de la convocatoria'||char(13)||char(10)||'Auxiliar de apoyo para el proyecto Hermes 67246 - Modelo de priorización de corredores para'||char(13)||char(10)||'la peatonalización del Centro Histórico de Bogotá mediante SIG y análisis multicriterio'||char(13)||char(10)||'Número de la convocatoria'||char(13)||char(10)||'2026-C2245 N.º de estudiantes '||char(13)||char(10)||'a vincular'||char(13)||char(10)||'2'||char(13)||char(10)||'Facultad, dependencia o '||char(13)||char(10)||'proyecto'||char(13)||char(10)||'Facultad de Ingeniería'||char(13)||char(10)||'Fecha de publicación de la '||char(13)||char(10)||'convocatoria 19 11 2026'||char(13)||char(10)||'Fecha de publicación de '||char(13)||char(10)||'resultados 13 11 2026'||char(13)||char(10)||'Requisitos Generales'||char(13)||char(10)||'(Art. 2 Acuerdo CSU 024 de '||char(13)||char(10)||'2022)'||char(13)||char(10)||'a. Tener la calidad de estudiante de pregrado o postgrado de la Universidad Nacional de Colombia. '||char(13)||char(10)||'b. Si las actividades a desarrollar están relacionadas con docencia, el estudiante deberá tener un '||char(13)||char(10)||'Promedio Aritmético Ponderado Acumulado - P.A.P.A. igual o superior a 3.5. para estudiantes de '||char(13)||char(10)||'pregrado, e igual o superior a 4.0 para estudiantes de posgrado. '||char(13)||char(10)||'c. Si las actividades a desarrollar están relacionadas con investigación, extensión, bienestar '||char(13)||char(10)||'universitario o de gestión administrativa el estudiante deberá tener un Promedio Aritmético '||char(13)||char(10)||'Ponderado Acumulado - P.A.P.A. igual o superior a 3.0. para estudiantes de pregrado, e igual o '||char(13)||char(10)||'superior a 4.0 para estudiantes de posgrado'||char(13)||char(10)||'d. No ostentar la calidad de monitor académico o becario, salvo para aquellos estudiantes que '||char(13)||char(10)||'obtuvieron la beca de posgrado por la distinción de Grado de Honor de la Universidad Nacional de '||char(13)||char(10)||'Colombia.'||char(13)||char(10)||'e. No tener calidad de funcionario público (administrativo o docente de planta) de la Universidad '||char(13)||char(10)||'Nacional de Colombia.'||char(13)||char(10)||'f. Durante el periodo lectivo el Estudiante Auxiliar debe mantener la calidad de estudiante e inscrita '||char(13)||char(10)||'al menos la carga mínima exigida por el Estatuto Estudiantil. '||char(13)||char(10)||'g. No haber tenido sanciones disciplinarias.'||char(13)||char(10)||'PARÁGRAFO 1. La figura de Estudiante Auxiliar podrá ser compatible con las modalidades de apoyo '||char(13)||char(10)||'a estudiantes en las cuales no se reciba una retribución económica por la realización de actividades y '||char(13)||char(10)||'que el desempeño como Estudiante Auxiliar no interfiera con el normal desarrollo de su actividad '||char(13)||char(10)||'académica. '||char(13)||char(10)||'PARÁGRAFO 2. Para los estudiantes de posgrado que se encuentren matriculados en el primer '||char(13)||char(10)||'periodo académico de un programade posgrado cumplir una de las siguientes condiciones, de '||char(13)||char(10)||'acuerdo con el tipo de admisión, así: '||char(13)||char(10)||'1. Admisión regular. Se privilegia a los que hayan obtenido los mayores puntajes de admisión.'||char(13)||char(10)||'2. Haber sido admitido por admisión automática, según el literal c del artículo 57 del Acuerdo 008 '||char(13)||char(10)||'de 2008 del Consejo Superior Universitario - Estatuto Estudiantil en sus disposiciones académicas.'||char(13)||char(10)||'3. Admisión mediante tránsito entre programas de posgrado, tener un promedio académico igual o '||char(13)||char(10)||'superior a 4.0 en el programa de posgrado desde el cual se aprobó el tránsito.'||char(13)||char(10)||'Perfil requerido Estudiante de Ingeniería Civil con avance del 50% de carrera que haya participado en un semillero'||char(13)||char(10)||'del área de tránsito, transporte o infraestructura'||char(13)||char(10)||'CRITERIOS DE SELECCIÓN Y EVALUACIÓN'||char(13)||char(10)||'Criterios Ponderación '||char(13)||char(10)||'(Asigne el peso porcentual de cada criterio)'||char(13)||char(10)||'1 PAPA 20'||char(13)||char(10)||'2 PBM 20'||char(13)||char(10)||'3 Hoja de vida 30'||char(13)||char(10)||'4 Entrevista 30'||char(13)||char(10)||'Sumatoria de '||char(13)||char(10)||'porcentajes 100','segmentacion_por_cabecera_heuristica','pendiente','Los límites de página son estimados; revisar original PDF.');
