INSERT INTO pagina_pdf (pagina_id,documento_id,numero_pagina,texto_extraido_literal,metodo_extraccion,estado_revision_visual,notas) VALUES (400302,4003,2,'Macroproceso: Formación'||char(13)||char(10)||'Proceso: Gestión Administrativa de Apoyo a la Formación'||char(13)||char(10)||'Formato selección estudiantes auxiliares'||char(13)||char(10)||'Código: U.FT.05.007.014 Versión: 2.0 Página 2 de 2'||char(13)||char(10)||'DATOS DE LOS PARTICIPANTES'||char(13)||char(10)||'No. Identificación'||char(13)||char(10)||'Puntaje por Criterio'||char(13)||char(10)||'(De 0 a 5) (PBM de 0 a 100)'||char(13)||char(10)||'*P.A.P.A. '||char(13)||char(10)||'O puntaje de '||char(13)||char(10)||'admisión '||char(13)||char(10)||'(PA) (SI/NO)'||char(13)||char(10)||'P.B.M.'||char(13)||char(10)||'(si '||char(13)||char(10)||'aplica)'||char(13)||char(10)||'1 2 3 4 5 6 7 Total Seleccionado'||char(13)||char(10)||'1 1121528985 3,9 36 16 13 23 30 82 X'||char(13)||char(10)||'2 1016912141 3,7 28 15 14 24 28 81 X'||char(13)||char(10)||'3 1001187737 3,7 50 15 10 25 26 76'||char(13)||char(10)||'• Se deben relacionar todos los participantes que aplicaron a la convocatoria.'||char(13)||char(10)||'• Si el (la-los) estudiante(s) incumple(n) alguno de los Requisitos mínimos no se debe continuar con la evaluación de la hoja de vida.'||char(13)||char(10)||'• En caso de empate en el puntaje total, se dará prelación a los estudiantes cuyos puntajes básicos de matrícula (PBM) sean los más '||char(13)||char(10)||'bajos. (En caso que aplique)'||char(13)||char(10)||'• Marque una X en la columna "Seleccionado" para identificar el (los) ganador(es) de la convocatoria.'||char(13)||char(10)||'• Marque con la palabra “Elegible” a el (la-los) estudiante(s) que quedará(n) en la lista de elegible(s).'||char(13)||char(10)||'Certifico que el (los) estudiante(s) seleccionado(s) fue(ron) consultado(s) y manifiesta(n) no recibir ningún otro beneficio '||char(13)||char(10)||'económico de la Universidad Nacional de Colombia y que no está(n) inhabilitado(s) para ser vinculado(s) como Estudiante(s) '||char(13)||char(10)||'Auxiliar(es), a su vez asumo la responsabilidad de todo el proceso de selección del estudiante.'||char(13)||char(10)||'En caso de que no se haya seleccionado a ningún estudiante como ganador de la convocatoria especifique el motivo:'||char(13)||char(10)||'Observaciones:'||char(13)||char(10)||'NOMBRE DEL '||char(13)||char(10)||'RESPONSABLE DE LA '||char(13)||char(10)||'EVALUACIÓN'||char(13)||char(10)||'William Castro García'||char(13)||char(10)||'CARGO Profesor Asociado'||char(13)||char(10)||'EXTENSIÓN 313-4940351'||char(13)||char(10)||'CORREO wcastrog@unal.edu.co'||char(13)||char(10)||'_________________________________'||char(13)||char(10)||'(Original Firmado'||char(13)||char(10)||'Los estudiantes que se postulen para la presente convocatoria aceptan que sus datos personales (nombre completo y/o documento de '||char(13)||char(10)||'identificación, BPM o puntaje de admisión y P.A.P.A) sean publicados al momento de dar a conocer los resultados del proceso de selección por '||char(13)||char(10)||'los canales de divulgación que la Universidad disponga para tal fin. En el marco normativo de la Ley 1581 de 2012, la Universidad Nacional de '||char(13)||char(10)||'Colombia se permite informar que la información personal recolectada mediante la presente Convocatoria de Estudiantes Auxiliares se rige '||char(13)||char(10)||'bajo los principios rectores del Régimen de Protección de Datos de la Universidad Nacional, Resolución de Rectoría No. 207 de 2021, en '||char(13)||char(10)||'especial el de Legalidad y Veracidad o calidad, la cual puede ser consultada en http://www.legal.unal.edu.co/rlunal/home/doc.jsp?d_i=97992. '||char(13)||char(10)||'Sus datos se encuentran bajo medidas que garantizan la seguridad, confidencialidad e integridad. Puede ejercer sus derechos como titular a '||char(13)||char(10)||'conocer, actualizar, rectificar y revocar las autorizaciones dadas a las finalidades aplicables a través de los canales dispuestos y disponibles en '||char(13)||char(10)||'https://unal.edu.co/ o en el e-mail protecdatos_na@unal.edu.co.','segmentacion_por_cabecera_heuristica','pendiente','Los límites de página son estimados; revisar original PDF.');
